import { Controller, Get, HttpCode, Post, Put, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

// 가정: 계좌번호 암호화 키는 설정에서 받아야 하나 출처가 없어 임시 상수로 둔다.
const ACCOUNT_KEY = 'partner-account-key';
// 가정: 목록 기본 크기와 최대 크기
const DEFAULT_SIZE = 20;
const MAX_SIZE = 200;
const DATE_PATTERN = /^\d{4}-\d{2}-\d{2}$/;
const ROLE = '예산·회계 담당자';

type Body = Record<string, unknown>;

function invalid(message: string): ApiError {
  return new ApiError(422, 'PARTNER_INPUT_INVALID', message);
}

function text(value: unknown, label: string, max: number): string | null {
  if (value === undefined || value === null) {
    return null;
  }
  if (typeof value !== 'string') {
    throw invalid(label + ' 형식이 올바르지 않습니다.');
  }
  const trimmed = value.trim();
  if (trimmed === '') {
    return null;
  }
  if (trimmed.length > max) {
    throw invalid(label + '은(는) ' + max + '자 이하여야 합니다.');
  }
  return trimmed;
}

function required(value: string | null, label: string): string {
  if (value === null) {
    throw invalid(label + '을(를) 입력하세요.');
  }
  return value;
}

function dateOf(value: unknown, label: string): string | null {
  const s = text(value, label, 10);
  if (s !== null && !DATE_PATTERN.test(s)) {
    throw invalid(label + ' 형식은 YYYY-MM-DD입니다.');
  }
  return s;
}

function partnerParams(data: Body): Body {
  const partnerType = required(text(data.partnerType, '거래처 유형', 10), '거래처 유형');
  if (partnerType !== '일반' && partnerType !== '금융') {
    throw invalid('거래처 유형은 일반 또는 금융이어야 합니다.');
  }
  const partnerName = required(text(data.partnerName, '거래처 명칭', 200), '거래처 명칭');
  const partnerCode = required(text(data.partnerCode, '거래처 코드', 30), '거래처 코드');
  if (typeof data.taxInvoiceYn !== 'boolean') {
    throw invalid('세금계산서 여부를 선택하세요.');
  }
  let projectId: string | null = null;
  if (data.projectId !== undefined && data.projectId !== null && data.projectId !== '') {
    projectId = String(data.projectId);
    if (!/^\d+$/.test(projectId)) {
      throw invalid('프로젝트 형식이 올바르지 않습니다.');
    }
  }
  const tradeStartDate = dateOf(data.tradeStartDate, '거래 시작일');
  const tradeEndDate = dateOf(data.tradeEndDate, '거래 종료일');
  if (tradeStartDate !== null && tradeEndDate !== null && tradeEndDate < tradeStartDate) {
    throw invalid('거래 종료일은 시작일보다 빠를 수 없습니다.');
  }
  return {
    partnerType,
    partnerName,
    partnerCode,
    projectId,
    partnerShortName: text(data.partnerShortName, '거래처 약칭', 100),
    businessRegNo: text(data.businessRegNo, '사업자등록번호', 10),
    representativeName: text(data.representativeName, '대표자명', 100),
    partnerCategory: text(data.partnerCategory, '거래처 분류', 100),
    region: text(data.region, '지역', 100),
    taxInvoiceYn: data.taxInvoiceYn,
    tradeStartDate,
    tradeEndDate,
    contactName: text(data.contactName, '담당자명', 100),
    contactPhone: text(data.contactPhone, '담당자 연락처', 30),
  };
}

type Db = Parameters<Parameters<typeof transaction>[0]>[0];

async function checkReferences(db: Db, params: Body, selfId: string | null): Promise<void> {
  const dup = await db.query(
    'SELECT partner_id FROM partner WHERE partner_code = :partnerCode AND (CAST(:selfId AS bigint) IS NULL OR partner_id <> CAST(:selfId AS bigint))',
    { partnerCode: params.partnerCode, selfId },
  );
  if (dup.length > 0) {
    throw new ApiError(409, 'PARTNER_CODE_DUPLICATED', '이미 사용 중인 거래처 코드입니다.');
  }
  if (params.projectId !== null) {
    const project = await db.query(
      'SELECT project_id FROM project WHERE project_id = CAST(:projectId AS bigint)',
      { projectId: params.projectId },
    );
    if (project.length === 0) {
      throw invalid('존재하지 않는 프로젝트입니다.');
    }
  }
}

const PARTNER_COLUMNS = [
  'partner_code', 'partner_name', 'partner_short_name', 'partner_type', 'business_reg_no',
  'representative_name', 'partner_category', 'region', 'tax_invoice_yn', 'project_id',
  'trade_start_date', 'trade_end_date', 'contact_name', 'contact_phone',
];

@Controller('api/v1')
export class FnSfr00204Controller {
  @Post('/partners')
  @HttpCode(200)
  async createPartner(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    const data = checks.inputOf(req.body);
    return transaction(async (db) => {
      const params = partnerParams(data);
      const bankName = text(data.bankName, '은행명', 100);
      const accountNo = text(data.accountNo, '계좌번호', 100);
      const accountHolder = text(data.accountHolder, '예금주', 100);
      const hasAccount = bankName !== null || accountNo !== null || accountHolder !== null;
      if (params.partnerType === '일반' && hasAccount) {
        throw new ApiError(422, 'PARTNER_ACCOUNT_NOT_ALLOWED', '일반 거래처에는 계좌정보를 등록할 수 없습니다.');
      }
      if (hasAccount && (bankName === null || accountNo === null)) {
        throw invalid('계좌정보는 은행명과 계좌번호를 함께 입력하세요.');
      }
      await checkReferences(db, params, null);
      const rows = await db.query(
        'INSERT INTO partner (project_id, partner_code, partner_name, partner_short_name, partner_type, business_reg_no, representative_name, partner_category, region, tax_invoice_yn, trade_start_date, trade_end_date, contact_name, contact_phone, created_at, updated_at) '
          + 'VALUES (CAST(:projectId AS bigint), :partnerCode, :partnerName, :partnerShortName, :partnerType, :businessRegNo, :representativeName, :partnerCategory, :region, :taxInvoiceYn, CAST(:tradeStartDate AS date), CAST(:tradeEndDate AS date), :contactName, :contactPhone, now(), now()) '
          + 'RETURNING partner_id AS "partnerId"',
        params,
      );
      const partnerId = rows[0].partnerId;
      if (hasAccount) {
        await db.execute(
          'INSERT INTO partner_account (partner_id, bank_name, account_no_enc, account_holder, use_yn, created_at, updated_at) '
            + 'VALUES (CAST(:partnerId AS bigint), :bankName, pgp_sym_encrypt(:accountNo, :accountKey), :accountHolder, :useYn, now(), now())',
          { partnerId, bankName, accountNo, accountHolder, accountKey: ACCOUNT_KEY, useYn: '사용' },
        );
      }
      return { partnerId };
    });
  }

  @Put('/partners/:partnerId')
  async updatePartner(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    const data = checks.inputOf(req.body);
    const idText = req.params['partnerId'];
    return transaction(async (db) => {
      if (!/^\d+$/.test(idText)) {
        throw new ApiError(404, 'PARTNER_NOT_FOUND', '거래처를 찾을 수 없습니다.');
      }
      const found = await db.query(
        'SELECT partner_id FROM partner WHERE partner_id = CAST(:partnerId AS bigint)',
        { partnerId: idText },
      );
      if (found.length === 0) {
        throw new ApiError(404, 'PARTNER_NOT_FOUND', '거래처를 찾을 수 없습니다.');
      }
      const params = partnerParams(data);
      await checkReferences(db, params, idText);
      await db.execute(
        'UPDATE partner SET project_id = CAST(:projectId AS bigint), partner_code = :partnerCode, partner_name = :partnerName, '
          + 'partner_short_name = :partnerShortName, partner_type = :partnerType, business_reg_no = :businessRegNo, '
          + 'representative_name = :representativeName, partner_category = :partnerCategory, region = :region, '
          + 'tax_invoice_yn = :taxInvoiceYn, trade_start_date = CAST(:tradeStartDate AS date), '
          + 'trade_end_date = CAST(:tradeEndDate AS date), contact_name = :contactName, contact_phone = :contactPhone, '
          + 'updated_at = now() WHERE partner_id = CAST(:partnerId AS bigint)',
        { ...params, partnerId: idText },
      );
      return { partnerId: Number(idText) };
    });
  }

  @Get('/partners')
  async listPartners(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    const query = checks.queryOf(req.query);
    const pageNo = Math.max(0, Math.floor(Number(query.page ?? 0)) || 0);
    const rawSize = Math.floor(Number(query.size ?? DEFAULT_SIZE)) || DEFAULT_SIZE;
    const size = Math.min(MAX_SIZE, Math.max(1, rawSize));
    const partnerName = text(query.partnerName, '거래처 명칭', 200);
    const partnerType = text(query.partnerType, '거래처 유형', 10);
    return transaction(async (db) => {
      const where = 'WHERE (CAST(:partnerName AS text) IS NULL OR partner_name LIKE (\'%\' || CAST(:partnerName AS text) || \'%\')) '
        + 'AND (CAST(:partnerType AS text) IS NULL OR partner_type = CAST(:partnerType AS text))';
      const items = await db.query(
        'SELECT partner_id AS "partnerId", partner_code AS "partnerCode", partner_name AS "partnerName", '
          + 'partner_type AS "partnerType", business_reg_no AS "businessRegNo", representative_name AS "representativeName" '
          + 'FROM partner ' + where + ' ORDER BY partner_id DESC LIMIT :size OFFSET :offset',
        { partnerName, partnerType, size, offset: pageNo * size },
      );
      const counts = await db.query(
        'SELECT COUNT(*) AS "total" FROM partner ' + where,
        { partnerName, partnerType },
      );
      return { items, page: pageNo, size, total: Number(counts[0].total) };
    });
  }
}

