import { useState } from 'react';
import {
  Badge,
  Band,
  DataTable,
  DateInput,
  Drawer,
  Field,
  Filters,
  Form,
  LookupSelect,
  Num,
  Pager,
  Select,
  TextInput,
  call,
  useData,
} from '../kit';
import type { Page, PageProps, Row } from '../kit';

const PAGE_SIZE = 20;
const TYPE_OPTIONS: [string, string][] = [['일반', '일반'], ['금융', '금융']];
const TAX_OPTIONS: [string, string][] = [['true', '예'], ['false', '아니오']];

interface DrawerState {
  editId: number | null;
}

function emptyForm(): Row {
  return {
    partnerType: '',
    partnerName: '',
    partnerCode: '',
    partnerShortName: '',
    businessRegNo: '',
    representativeName: '',
    projectId: '',
    partnerCategory: '',
    region: '',
    taxInvoiceYn: '',
    tradeStartDate: '',
    tradeEndDate: '',
    contactName: '',
    contactPhone: '',
    bankName: '',
    accountNo: '',
    accountHolder: '',
  };
}

export default function FnSfr00204Page({ role, notify }: PageProps) {
  const [name, setName] = useState('');
  const [type, setType] = useState('');
  const [applied, setApplied] = useState<Row>({});
  const [page, setPage] = useState(0);
  const [drawer, setDrawer] = useState<DrawerState | null>(null);
  const [form, setForm] = useState<Row>(emptyForm());

  const list = useData<Page>(
    () => call<Page>('GET', '/partners', role, undefined, { ...applied, page, size: PAGE_SIZE }),
    [role, applied, page],
  );

  const set = (key: string, value: unknown) => {
    setForm({ ...form, [key]: value });
  };

  const search = () => {
    setPage(0);
    setApplied({ partnerName: name, partnerType: type });
  };

  const reset = () => {
    setName('');
    setType('');
    setPage(0);
    setApplied({});
  };

  const openCreate = () => {
    setForm(emptyForm());
    setDrawer({ editId: null });
  };

  const openEdit = (row: Row) => {
    setForm({
      ...emptyForm(),
      partnerType: row.partnerType ?? '',
      partnerName: row.partnerName ?? '',
      partnerCode: row.partnerCode ?? '',
      businessRegNo: row.businessRegNo ?? '',
      representativeName: row.representativeName ?? '',
    });
    setDrawer({ editId: Number(row.partnerId) });
  };

  const submit = async () => {
    if (!form.partnerType) {
      throw new Error('거래처 유형을 선택하세요.');
    }
    if (!String(form.partnerName).trim()) {
      throw new Error('거래처 명칭을 입력하세요.');
    }
    if (!String(form.partnerCode).trim()) {
      throw new Error('거래처 코드를 입력하세요.');
    }
    if (form.taxInvoiceYn === '') {
      throw new Error('세금계산서 여부를 선택하세요.');
    }
    const body: Row = {
      ...form,
      taxInvoiceYn: form.taxInvoiceYn === 'true',
      projectId: form.projectId === '' ? undefined : form.projectId,
    };
    if (drawer?.editId != null) {
      delete body.bankName;
      delete body.accountNo;
      delete body.accountHolder;
      await call('PUT', '/partners/' + drawer.editId, role, body);
      notify('거래처를 수정했습니다.');
    } else {
      await call('POST', '/partners', role, body);
      notify('거래처를 등록했습니다.');
    }
    setDrawer(null);
    list.reload();
  };

  const isEdit = drawer?.editId != null;

  return (
    <div className="bento">
      <section className="box span-4">
        <h2>전체 거래처</h2>
        <Num value={list.data?.total ?? 0} />
      </section>
      <section className="box span-8">
        <h2>거래처 목록</h2>
        <Filters onSearch={search} onReset={reset}>
          <Field label="거래처 명칭">
            <TextInput value={name} onChange={setName} />
          </Field>
          <Field label="거래처 유형">
            <Select value={type} onChange={setType} options={TYPE_OPTIONS} />
          </Field>
        </Filters>
        <Band total={list.data?.total}>
          <button type="button" onClick={openCreate}>거래처 등록</button>
        </Band>
        {list.error ? <p>{list.error}</p> : null}
        <DataTable
          rows={list.data?.items ?? []}
          empty="거래처가 없습니다."
          columns={[
            { key: 'partnerCode', label: '거래처 코드' },
            { key: 'partnerName', label: '거래처 명칭' },
            { key: 'partnerType', label: '거래처 유형', render: (r) => <Badge value={r.partnerType} /> },
            { key: 'businessRegNo', label: '사업자등록번호' },
            { key: 'representativeName', label: '대표자명' },
            {
              key: 'partnerId',
              label: '관리',
              render: (r) => (
                <button type="button" onClick={() => openEdit(r)}>수정</button>
              ),
            },
          ]}
        />
        <Pager
          page={list.data?.page ?? 0}
          size={list.data?.size ?? PAGE_SIZE}
          total={list.data?.total ?? 0}
          onPage={setPage}
        />
      </section>
      {drawer ? (
        <Drawer title={isEdit ? '거래처 수정' : '거래처 등록'} onClose={() => setDrawer(null)}>
          <Form
            onSubmit={submit}
            submit={isEdit ? '수정' : '등록'}
            note={isEdit ? '수정은 전체 항목을 다시 입력합니다.' : undefined}
          >
            <Field label="거래처 유형" required>
              <Select value={form.partnerType} onChange={(v) => set('partnerType', v)} options={TYPE_OPTIONS} />
            </Field>
            <Field label="거래처 명칭" required>
              <TextInput value={form.partnerName} onChange={(v) => set('partnerName', v)} />
            </Field>
            <Field label="거래처 약칭">
              <TextInput value={form.partnerShortName} onChange={(v) => set('partnerShortName', v)} />
            </Field>
            <Field label="거래처 코드" required>
              <TextInput value={form.partnerCode} onChange={(v) => set('partnerCode', v)} />
            </Field>
            <Field label="사업자등록번호">
              <TextInput value={form.businessRegNo} onChange={(v) => set('businessRegNo', v)} />
            </Field>
            <Field label="대표자명">
              <TextInput value={form.representativeName} onChange={(v) => set('representativeName', v)} />
            </Field>
            <Field label="프로젝트">
              <LookupSelect table="project" role={role} value={form.projectId} onChange={(v) => set('projectId', v)} />
            </Field>
            <Field label="거래처 분류">
              <TextInput value={form.partnerCategory} onChange={(v) => set('partnerCategory', v)} />
            </Field>
            <Field label="지역">
              <TextInput value={form.region} onChange={(v) => set('region', v)} />
            </Field>
            <Field label="세금계산서 여부" required>
              <Select value={form.taxInvoiceYn} onChange={(v) => set('taxInvoiceYn', v)} options={TAX_OPTIONS} />
            </Field>
            <Field label="거래 시작일">
              <DateInput value={form.tradeStartDate} onChange={(v) => set('tradeStartDate', v)} />
            </Field>
            <Field label="거래 종료일">
              <DateInput value={form.tradeEndDate} onChange={(v) => set('tradeEndDate', v)} />
            </Field>
            <Field label="담당자명">
              <TextInput value={form.contactName} onChange={(v) => set('contactName', v)} />
            </Field>
            <Field label="담당자 연락처">
              <TextInput value={form.contactPhone} onChange={(v) => set('contactPhone', v)} />
            </Field>
            {!isEdit && form.partnerType === '금융' ? (
              <>
                <Field label="은행명">
                  <TextInput value={form.bankName} onChange={(v) => set('bankName', v)} />
                </Field>
                <Field label="계좌번호">
                  <TextInput value={form.accountNo} onChange={(v) => set('accountNo', v)} />
                </Field>
                <Field label="예금주">
                  <TextInput value={form.accountHolder} onChange={(v) => set('accountHolder', v)} />
                </Field>
              </>
            ) : null}
          </Form>
        </Drawer>
      ) : null}
    </div>
  );
}
